// The Lucide icons of AWE 5 (#885), built from the lucide-static package each client pins in its devDependencies:
// - the sprite both clients serve: one <symbol id="name" viewBox="0 0 24 24"> per icon, without presentation
//   attributes, so CSS sets the stroke (1.75px) and the colour (currentColor) as in the prototype sprite;
// - lucide-names.json, the names (and the aliases of older names) the icon resolver accepts for icon="lucide:<name>".
// The sprite is generated by the build of each client (LucideSpritePlugin) and is not kept in the repository.
//
// Usage: node lucide-sprite.cjs <lucide-static folder> <sprite file>
//        node lucide-sprite.cjs --names <lucide-static folder>   (rewrites lucide-names.json next to this script)
const fs = require("fs");
const path = require("path");

const PLUGIN_NAME = "LucideSpritePlugin";
const NAMES_FILE = path.join(__dirname, "lucide-names.json");
// Attributes CSS sets on the icon: the sprite never carries them (width and height of a shape are its geometry)
const PRESENTATION = /^(stroke|class|style)/;

const readJson = file => JSON.parse(fs.readFileSync(file, "utf8"));
const escapeAttribute = value => String(value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");

// The shapes of an icon file, to tell an alias (an older name) from its current icon
const shapesOf = file => fs.readFileSync(file, "utf8").split("\n").filter(line => /^\s+<[a-z]/.test(line))
  .map(line => line.trim()).join("");

/**
 * Read the icons of a lucide-static package
 * @param {string} lucideDir Folder of the lucide-static package
 * @returns {{version: string, iconNodes: object, aliases: object}} Version, shapes per icon and current name per alias
 */
const readLucide = lucideDir => {
  const {version} = readJson(path.join(lucideDir, "package.json"));
  const iconNodes = readJson(path.join(lucideDir, "icon-nodes.json"));
  const iconsDir = path.join(lucideDir, "icons");
  const byShapes = new Map(Object.keys(iconNodes).map(name => [shapesOf(path.join(iconsDir, `${name}.svg`)), name]));
  const aliases = Object.fromEntries(fs.readdirSync(iconsDir)
    .filter(file => file.endsWith(".svg"))
    .map(file => file.slice(0, -".svg".length))
    .filter(name => !(name in iconNodes))
    .sort()
    .map(name => [name, byShapes.get(shapesOf(path.join(iconsDir, `${name}.svg`)))])
    .filter(([, current]) => current));
  const license = fs.readFileSync(path.join(lucideDir, "LICENSE"), "utf8").trim();
  return {version, iconNodes, aliases, license};
};

const renderNode = ([tag, attributes]) => {
  const rendered = Object.entries(attributes)
    .filter(([name, value]) => !PRESENTATION.test(name) && (name !== "fill" || value === "currentColor"))
    .map(([name, value]) => ` ${name}="${escapeAttribute(value)}"`).join("");
  return `<${tag}${rendered}/>`;
};

/**
 * Build the SVG sprite with every Lucide icon
 * @param {{version: string, iconNodes: object, license: string}} lucide Icons read with readLucide
 * @returns {string} Sprite, with the licence of lucide-static (the ISC licence asks for it in every copy)
 */
const buildSprite = ({version, iconNodes, license}) => [
  // An XML comment cannot hold a double hyphen (the licence separates its parts with ---)
  `<!-- Lucide icons (lucide-static ${version}) - generated by AWE, do not edit\n\n${license.replace(/-{2,}/g, "* * *")}\n-->`,
  "<svg xmlns=\"http://www.w3.org/2000/svg\">",
  ...Object.entries(iconNodes).map(([name, nodes]) =>
    `<symbol id="${escapeAttribute(name)}" viewBox="0 0 24 24">${nodes.map(renderNode).join("")}</symbol>`),
  "</svg>",
  ""
].join("\n");

/**
 * Build the list of Lucide names the icon resolver accepts
 * @param {{version: string, iconNodes: object, aliases: object}} lucide Icons read with readLucide
 * @returns {{version: string, icons: string[], aliases: object}} Names
 */
const buildNames = ({version, iconNodes, aliases}) => ({version, icons: Object.keys(iconNodes), aliases});

/**
 * Webpack plugin that adds the Lucide sprite to the build output
 */
class LucideSpritePlugin {
  /**
   * @param {{lucideDir: string, filename: string}} options Folder of lucide-static and path of the sprite in the output
   */
  constructor({lucideDir, filename}) {
    this.lucideDir = lucideDir;
    this.filename = filename;
  }

  apply(compiler) {
    const {Compilation, sources} = compiler.webpack;
    compiler.hooks.thisCompilation.tap(PLUGIN_NAME, compilation => {
      compilation.hooks.processAssets.tap({name: PLUGIN_NAME, stage: Compilation.PROCESS_ASSETS_STAGE_ADDITIONAL}, () => {
        compilation.fileDependencies.add(path.join(this.lucideDir, "package.json"));
        compilation.emitAsset(this.filename, new sources.RawSource(buildSprite(readLucide(this.lucideDir))));
      });
    });
  }
}

module.exports = {readLucide, buildSprite, buildNames, LucideSpritePlugin};

if (require.main === module) {
  const [first, second] = process.argv.slice(2);
  if (first === "--names" && second) {
    fs.writeFileSync(NAMES_FILE, `${JSON.stringify(buildNames(readLucide(path.resolve(second))), null, 2)}\n`);
  } else if (first && second) {
    fs.writeFileSync(path.resolve(second), buildSprite(readLucide(path.resolve(first))));
  } else {
    // eslint-disable-next-line no-console
    console.error("Usage: node lucide-sprite.cjs <lucide-static folder> <sprite file> | --names <lucide-static folder>");
    process.exitCode = 1;
  }
}
